class Solution {
public:
    int bestRotation(vector<int>& nums) {
        int n = nums.size();
        vector<int> change(n, 0);
        int score = 0;
        for (int i = 0; i < n; ++i) {
            if (nums[i] <= i) ++score;
            int lose = (i - nums[i] + 1 + n) % n;
            int gain = (i + 1) % n;
            --change[lose];
            ++change[gain];
            if (lose > gain) --change[0];
        }
        int best = 0, highest = score;
        for (int k = 1; k < n; ++k) {
            score += change[k];
            if (score > highest) {
                highest = score;
                best = k;
            }
        }
        return best;
    }
};
